{
  "assessment": "The paper provides a detailed numerical study of spontaneous quantum turbulence in a 2D BEC formed via a thermal quench, with quantitative controls (quench time, temperature), readouts (vortex number, energy spectra, structure functions), and mechanisms (KZM, Kolmogorov scaling). The evidence supports authoring an interactive experiment.",
  "case_authoring_ready": true,
  "source": {
    "citation": "Seong-Ho Shinn et al., Spontaneous Quantum Turbulence in a Newborn Bose-Einstein Condensate via the Kibble-Zurek Mechanism, Physical Review Letters (2026), DOI:10.1103/b16v-hwp2",
    "journal_doi": "10.1103/b16v-hwp2",
    "arxiv_versioned_id": "2506.21670v3"
  },
  "paper_scope": "The paper uses numerical simulations of the 2D stochastic projected Gross-Pitaevskii equation to study the formation of a Bose-Einstein condensate via a thermal quench, focusing on the emergence of spontaneous quantum turbulence characterized by vortex proliferation and Kolmogorov scaling of the incompressible kinetic energy spectrum. It establishes Kibble-Zurek universality of the vortex number and energy spectra, and analyzes velocity structure functions and compressible energy spectra.",
  "mechanisms": [
    {
      "mechanism_id": "kibble_zurek_mechanism",
      "statement": "The Kibble-Zurek mechanism predicts universal scaling of defect density and freeze-out time in a finite-rate phase transition, based on diverging correlation length and relaxation time near the critical point.",
      "equations": [
        "\\hat\\xi = \\xi_0 (\\tau_Q/\\tau_0)^{\\nu/(1+z\\nu)}",
        "\\rho_v \\propto 1/\\hat\\xi^2 = (1/\\xi_0^2)(\\tau_0/\\tau_Q)^{2\\nu/(1+z\\nu)}",
        "\\hat{t} = (\\tau_0 \\tau_Q^{z\\nu})^{1/(1+z\\nu)}"
      ],
      "variable_names": ["\\hat\\xi", "\\rho_v", "\\hat{t}", "\\tau_Q", "\\nu", "z", "\\xi_0", "\\tau_0"],
      "parameters": [
        {
          "name": "nu",
          "value": 0.5,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "correlation-length critical exponent (mean-field value)",
          "anchors": [
            {
              "line_start": 153,
              "line_end": 153,
              "support": "Using the mean-field values of the critical exponents ν = 1/2 and z = 2"
            }
          ]
        },
        {
          "name": "z",
          "value": 2,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "dynamic critical exponent (mean-field value)",
          "anchors": [
            {
              "line_start": 153,
              "line_end": 153,
              "support": "Using the mean-field values of the critical exponents ν = 1/2 and z = 2"
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 118,
          "line_end": 124,
          "support": "KZM uses divergence of correlation length ξ=ξ0/|ε|^ν and relaxation time τ=τ0/|ε|^{zν}; predicts vortex density scaling ρ_v ∝ 1/ξ̂^2 and freeze-out time t̂."
        },
        {
          "line_start": 153,
          "line_end": 156,
          "support": "With mean-field exponents ν=1/2, z=2, equilibration time scales as t_eq ∝ τ_Q^{1/2}."
        }
      ]
    },
    {
      "mechanism_id": "kolmogorov_scaling",
      "statement": "In the inertial range, the incompressible kinetic energy spectrum follows a k^{-5/3} power law, derived from dimensional arguments assuming constant energy flux and negligible viscosity.",
      "equations": [
        "E_i(k) \\propto k^{-5/3}"
      ],
      "variable_names": ["E_i(k)", "k"],
      "parameters": [],
      "anchors": [
        {
          "line_start": 200,
          "line_end": 204,
          "support": "With assumptions of constant energy change per unit time and negligible viscosity, dimensional arguments imply k^{-5/3} scaling."
        },
        {
          "line_start": 238,
          "line_end": 239,
          "support": "Fitted exponents in inertial range agree with Kolmogorov scaling value 5/3≈1.67 within numerical uncertainty."
        }
      ]
    },
    {
      "mechanism_id": "vortex_core_scaling",
      "statement": "At high momenta, the energy spectrum exhibits a k^{-3} power law reflecting the short-range structure of the vortex core, which is unrelated to turbulence.",
      "equations": [
        "E_i(k) \\propto k^{-3}"
      ],
      "variable_names": ["E_i(k)", "k"],
      "parameters": [],
      "anchors": [
        {
          "line_start": 207,
          "line_end": 210,
          "support": "At higher momenta, the inertial range is interrupted by a second power law E_i(k) ∝ k^{-3} reflecting short-range vortex core properties."
        }
      ]
    },
    {
      "mechanism_id": "kz_universality_of_spectrum",
      "statement": "The incompressible kinetic energy spectrum exhibits a universal collapse when rescaled by the Kibble-Zurek correlation length and associated energy scale, with scaling exponents derived from the KZM.",
      "equations": [
        "E_i(k, \\tau_Q) = A(\\tau_Q) F(k\\hat\\xi)",
        "A(\\tau_Q) \\propto \\tau_Q^{-(1+\\nu)/(1+z\\nu)}",
        "k \\to k \\tau_Q^{\\nu/(1+z\\nu)}, \\quad E_i(k) \\to E_i(k) \\tau_Q^{(1+\\nu)/(1+z\\nu)}"
      ],
      "variable_names": ["E_i(k)", "k", "\\hat\\xi", "\\tau_Q", "\\nu", "z"],
      "parameters": [],
      "anchors": [
        {
          "line_start": 314,
          "line_end": 323,
          "support": "Assuming scaling ansatz E_i(k,τ_Q)=A(τ_Q)F(kξ̂), using E_i ∝ τ_Q^{-(1+2ν)/(1+zν)} and ξ̂ ∝ τ_Q^{ν/(1+zν)} gives A(τ_Q) ∝ τ_Q^{-(1+ν)/(1+zν)}, implying collapse under rescaling shown in Eq. (Ei_scaling)."
        }
      ]
    },
    {
      "mechanism_id": "compressible_energy_phonon_mechanism",
      "statement": "At low temperature, the compressible kinetic energy is dominated by phonons emitted during vortex-antivortex annihilation, leading to a universal scaling with quench time.",
      "equations": [
        "E_p^{tot} \\propto \\tau_Q^{-(3ν+1/2)/(1+zν)}",
        "E_p^{tot}(k) \\propto \\tau_Q^{-(2ν+1/2)/(1+zν)} G(k \\tau_Q^{ν/(1+zν)})"
      ],
      "variable_names": ["E_p^{tot}", "E_p^{tot}(k)", "\\tau_Q", "\\nu", "z"],
      "parameters": [],
      "anchors": [
        {
          "line_start": 618,
          "line_end": 660,
          "support": "Assuming E_c originates from vortex-antivortex annihilations, phonon number N_p ∝ n_v ∝ τ_Q^{-2ν/(1+zν)}, each phonon energy k c_s with c_s=√μ, and μ(t_eq) ∝ τ_Q^{-1/(1+zν)}, yields E_p^{tot} ∝ τ_Q^{-(3ν+1/2)/(1+zν)} and spectral density E_p^{tot}(k) ∝ τ_Q^{-(2ν+1/2)/(1+zν)} G(k τ_Q^{ν/(1+zν)})."
        }
      ]
    }
  ],
